import type { Meta, StoryObj } from '@storybook/react-webpack5';
import { fn } from 'storybook/test';
import React, { useState } from 'react';
import { Box } from '@chakra-ui/react';
import { MemoryRouter } from 'react-router-dom';
import { ZimmProductCardContent } from './index';
import type { ZimmProductCardContentProps } from './index';
import type { ZimmSizeChipValue } from '../zimmSizeChipGroup';

const SIZES: ZimmSizeChipValue[] = [
  { value: 'xs', label: 'XS' },
  { value: 's', label: 'S' },
  { value: 'm', label: 'M' },
  { value: 'l', label: 'L' },
];

const meta: Meta<typeof ZimmProductCardContent> = {
  title: 'Commerce/ZimmProductCardContent',
  component: ZimmProductCardContent,
  parameters: { layout: 'padded' },
  decorators: [
    // The composed product-name link renders a real react-router-dom <Link>, which requires a
    // Router context — same requirement and fix as zimmColourSwatch/index.stories.tsx.
    (Story) => (
      <MemoryRouter>
        {/* Roughly a real card's own width, matching zimmProductCardMedia/index.stories.tsx's
            decorator so this reads naturally as the block that sits beneath that component. */}
        <Box width="320px">
          <Story />
        </Box>
      </MemoryRouter>
    ),
  ],
};
export default meta;

type Story = StoryObj<typeof ZimmProductCardContent>;

/** Minimal, PLP-shaped default: name link, bag action, price — no attributes, no size chips. */
export const Default: Story = {
  args: {
    name: 'Natura Long Sleeve Linen Mini Dress',
    headingLevel: 'h3',
    href: '/product/123',
    currentPrice: '$595.00',
    showAttributes: false,
    showBag: true,
    onAddToBag: fn(),
    showSizeChips: false,
    showNotifyMe: false,
  },
};

/** Wishlist-shaped: colour + size shown as plain text beneath the name. */
export const WithAttributes: Story = {
  args: {
    ...Default.args,
    showAttributes: true,
    colour: 'Ivory',
    size: 'M',
  },
};

/**
 * Wraps `ZimmProductCardContent` so `selectedSizeChipValue` is genuinely live rather than a
 * static arg — neither this component nor the `ZimmSizeChipGroup` it composes tracks selection
 * itself (both are correctly controlled components), so a story that wants a chip click to
 * visually select must own that state itself, the same pattern
 * zimmProductCard/index.stories.tsx's `Default` story already uses via its own `DefaultExample`.
 * Unlike that file, `ZimmProductCardContentProps` is a single flat type, not a discriminated
 * union keyed by `variation` — `selectedSizeChipValue`/`onSizeChipSelect` are already valid
 * (optional) members on every value of the type, so `{...args, selectedSizeChipValue,
 * onSizeChipSelect}` needs no narrowing before it assigns back to `ZimmProductCardContentProps`,
 * unlike that other file's `propsWithLiveSelection`. `handleSizeChipSelect` still fires the
 * original `args.onSizeChipSelect` (the `fn()` spy below) so Storybook's Actions panel keeps
 * logging the click.
 */
const WithSizeChipsExample = (args: ZimmProductCardContentProps) => {
  const [selectedSizeChipValue, setSelectedSizeChipValue] = useState<string | undefined>('m');
  const handleSizeChipSelect = (value: string) => {
    setSelectedSizeChipValue(value);
    args.onSizeChipSelect?.(value);
  };
  return (
    <ZimmProductCardContent
      {...args}
      selectedSizeChipValue={selectedSizeChipValue}
      onSizeChipSelect={handleSizeChipSelect}
    />
  );
};

/** PLP-shaped: the size-chip picker renders in place of the attributes line. Size chips are
 *  genuinely interactive here, not a static snapshot — starts pre-selected at 'M'; click a
 *  different chip to see the live selection move. Rendered via `WithSizeChipsExample` above,
 *  which owns `selectedSizeChipValue` as local state; every other arg below is unchanged. */
export const WithSizeChips: Story = {
  args: {
    ...Default.args,
    showSizeChips: true,
    sizeChipValues: SIZES,
    selectedSizeChipValue: 'm',
    onSizeChipSelect: fn(),
  },
  render: (args) => <WithSizeChipsExample {...args} />,
};

/** Out-of-stock: the bag button is present but disabled, and the notify-me CTA takes its place
 *  as the available action. */
export const Unavailable: Story = {
  args: {
    ...Default.args,
    isUnavailable: true,
    showNotifyMe: true,
    onNotifyMe: fn(),
  },
};

/** A variant re-fetch in progress — ZimmProductPrice renders its own invisible placeholder,
 *  preserving the layout slot rather than collapsing it. */
export const LoadingPrice: Story = {
  args: {
    ...Default.args,
    currentPrice: undefined,
    isPriceLoading: true,
  },
};

