import React, { useEffect, useRef, useState } from 'react';
import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
import { defineMessages, useIntl } from 'react-intl';
import { ZimmSizeChip } from '../../atoms/zimmSizeChip';

const messages = defineMessages({
  groupLabel: { id: 'size_chips.group.label', defaultMessage: 'Select a size' },
});

const ZIMM_SIZE_CHIP_GROUP_RECIPE = 'ZimmSizeChipGroup';

/** One selectable size as the molecule expects it — pre-mapped from the raw SFCC shape. */
export type ZimmSizeChipValue = {
  value: string;
  label: string;
  /**
   * Mirrors SFCC's orderable/stock flag for this size. Unlike ZimmColourSwatchGroup's colours
   * (withheld entirely when unavailable), an unavailable size is shown disabled so the shopper
   * can still see the full size run — the size-chip Figma component set includes a dedicated
   * Disabled state for exactly this.
   */
  isDisabled?: boolean;
};

type ZimmSizeChipGroupProps = {
  values: ZimmSizeChipValue[];
  /** Currently selected size value (from URL / variation params). */
  selectedValue?: string;
  /**
   * Selection callback. Called on click and on arrow-key navigation landing on a new chip.
   * Never called for a disabled size under any input method.
   */
  onSelect?: (value: string) => void;
};

/** Index of the first non-disabled entry in `list`, or -1 when every entry is disabled. */
const firstEnabledIndex = (list: ZimmSizeChipValue[]): number => list.findIndex((v) => !v.isDisabled);

/**
 * The roving-tabindex/selection target: the selected value's index when it is itself enabled,
 * else the first enabled entry. Kept as a standalone pure function (rather than a closure over
 * component props) so the effect below can list its real inputs (`list`, `selected`) directly
 * as dependencies, with nothing left out for eslint's exhaustive-deps to flag.
 */
const computeFocusIndex = (list: ZimmSizeChipValue[], selected: string | undefined): number => {
  const selectedIndex = list.findIndex((v) => v.value === selected);
  return selectedIndex >= 0 && !list[selectedIndex].isDisabled ? selectedIndex : firstEnabledIndex(list);
};

/**
 * Molecule — the full PDP size-chip group: a `[role=radiogroup]` row of ZimmSizeChip atoms with
 * roving tabindex and keyboard navigation, adapted from ZimmColourSwatchGroup's
 * handleSwatchesKeyDown for a row with no pagination and a real per-chip disabled state (arrow
 * navigation must skip a disabled chip rather than land on or select it).
 *
 * When exactly one size is offered, the size-chip Figma component set's other Type applies: a
 * single non-interactive label renders instead of a one-item radiogroup — a genuinely
 * different, non-interactive component, not a radiogroup with one item.
 */
export const ZimmSizeChipGroup = ({ values, selectedValue, onSelect }: ZimmSizeChipGroupProps) => {
  const intl = useIntl();
  const groupLabel = intl.formatMessage(messages.groupLabel);
  const styles = useMultiStyleConfig(ZIMM_SIZE_CHIP_GROUP_RECIPE, {});

  // Roving-tabindex target, tracked as its own state rather than derived fresh every render —
  // arrow-key navigation updates it directly so the tab stop (and the imperative focus below)
  // moves within a single interaction, without depending on a controlling parent re-passing a
  // new `selectedValue` prop first.
  const [focusIndex, setFocusIndex] = useState(() => computeFocusIndex(values, selectedValue));

  // Re-sync the roving tab stop whenever the selected value or the list itself changes from
  // outside this component (e.g. a controlling page changing colour, which can change which
  // sizes are disabled).
  useEffect(() => {
    setFocusIndex(computeFocusIndex(values, selectedValue));
  }, [values, selectedValue]);

  const radiogroupRef = useRef<HTMLDivElement>(null);
  const shouldRefocus = useRef(false);

  // Imperative focus after arrow-key navigation — mirrors ZimmColourSwatchGroup's own
  // hasNavigated-ref pattern, adapted to fire off this component's own focusIndex state
  // directly rather than waiting on a selectedValue round-trip through a controlling parent.
  useEffect(() => {
    if (!shouldRefocus.current) return;
    shouldRefocus.current = false;
    const target = values[focusIndex];
    if (!target) return;
    const el = radiogroupRef.current?.querySelector(`[data-size-value="${target.value}"]`);
    (el as HTMLElement | null)?.focus();
  }, [focusIndex, values]);

  const selectIndex = (index: number, { refocus }: { refocus: boolean }) => {
    const target = values[index];
    if (!target || target.isDisabled) return;
    setFocusIndex(index);
    shouldRefocus.current = refocus;
    onSelect?.(target.value);
  };

  const handleChipsKeyDown = (e: React.KeyboardEvent<HTMLDivElement>) => {
    if (!['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown'].includes(e.key)) return;
    e.preventDefault();
    if (values.length === 0) return;

    // Derive current index from the focused element's data-size-value — a unique value
    // identity that survives duplicate display labels, same reasoning as
    // zimmColourSwatchGroup's own data-swatch-value lookup.
    const focusedValue = (document.activeElement as HTMLElement | null)?.getAttribute('data-size-value');
    const focusedIndex = focusedValue ? values.findIndex((v) => v.value === focusedValue) : -1;
    const currentIndex = focusedIndex >= 0 ? focusedIndex : focusIndex;
    if (currentIndex < 0) return; // every chip disabled — nothing to navigate from

    const step = e.key === 'ArrowRight' || e.key === 'ArrowDown' ? 1 : -1;

    let nextIndex = currentIndex;
    for (let attempt = 0; attempt < values.length; attempt += 1) {
      nextIndex = (nextIndex + step + values.length) % values.length;
      if (!values[nextIndex].isDisabled) {
        selectIndex(nextIndex, { refocus: true });
        return;
      }
    }
    // Looped through every chip and found none enabled — nothing to do.
  };

  // Nothing offered — suppress the group entirely rather than render an empty radiogroup, same
  // "nothing to show" precedent as zimmColourSwatchGroup's own offered.length === 0 guard.
  if (values.length === 0) return null;

  if (values.length === 1) {
    return (
      <chakra.span __css={styles.oneSize} data-testid="size-chip-one-size">
        {values[0].label}
      </chakra.span>
    );
  }

  return (
    <chakra.div
      role="radiogroup"
      aria-label={groupLabel}
      ref={radiogroupRef}
      __css={styles.radiogroup}
      onKeyDown={handleChipsKeyDown}
    >
      {values.map((v, i) => (
        <ZimmSizeChip
          key={v.value}
          value={v.value}
          label={v.label}
          isSelected={v.value === selectedValue}
          isDisabled={v.isDisabled}
          isFocusable={i === focusIndex}
          onSelect={() => selectIndex(i, { refocus: false })}
        />
      ))}
    </chakra.div>
  );
};

export default ZimmSizeChipGroup;

import React from 'react';
import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
import { Link as RouteLink } from 'react-router-dom';
import { defineMessages, useIntl } from 'react-intl';
import { ZimmProductName } from '../../atoms/zimmProductName';
import { ZimmProductPrice } from '../../atoms/zimmProductPrice';
import { ZimmIcon } from '../../atoms/zimmIcon';
import { ZimmSizeChipGroup } from '../zimmSizeChipGroup';
import type { ZimmSizeChipValue } from '../zimmSizeChipGroup';
import { CARD_SLOT } from '../../zimmProductCardShared';

/**
 * Selector contract for a later step (the ZimmProductCard organism, SFCC-236 Step 6): stable
 * `data-card-slot` values on this component's own DOM so that organism's own recipe can target
 * these descendants for hover-reveal styling without reaching into implementation details.
 * Do not rename these values without updating that recipe too — mirrors the same contract
 * `zimmProductCardMedia/index.tsx` documents for its own slots:
 *   - "content"   — the outermost element (this component's root).
 *   - "price"     — the price wrapper. Always rendered regardless of variation; the organism's
 *                   own CSS is what shows/hides it on hover per variation (see the `showBag`/
 *                   `showSizeChips` props below), not this component.
 *   - "sizeChips" — the size-chip-group wrapper (present only when `showSizeChips` is true).
 *                   Always rendered in the DOM per Figma's `hidden=true` default on the "Size
 *                   Selector instance" node — the organism's hover-reveal CSS is what handles
 *                   visibility, not this component's own recipe (see zimmProductCardContent.css.ts).
 *   - "bag"       — the bag-button wrapper (present only when `showBag` is true). Added later
 *                   than the three above, for the organism's own mobile-breakpoint hide rule
 *                   (Figma: PLP/PDP's Mobile Card-content instances have the bag icon's `Icons`
 *                   frame `hidden="true"`; Desktop and Wishlist's own Mobile instance do not) — a
 *                   viewport-width concern, not a hover one, but the same
 *                   "this component always renders it, the organism's CSS decides visibility"
 *                   division of responsibility as the other slots.
 */

// Same import base SFCC's own swatch-group/swatch.jsx uses for its `RouteLink`, and the same
// reasoning zimmColourSwatch/index.tsx already documents: a router `Link` delivers "URL updates
// without a full page reload" for real. Confirmed directly (no overrides/app/components/link/
// directory exists on disk) — there is no overrides/.../link equivalent to reuse instead.
const ProductNameLink = chakra(RouteLink);

const messages = defineMessages({
  // Deliberately generic, not name-interpolated ("Add {name} to bag") — no such requirement was
  // given, and the visible product name already sits immediately to this button's left in the
  // same row, so the accessible name does not need to repeat it.
  addToBag: { id: 'product_card_content.bag.add_to_bag', defaultMessage: 'Add to bag' },
  // Figma node 40002163:41468 (Desktop, Hover, PLP/PDP, Unavailable=True) — an instance of the
  // shared CTA/Link atom (40001908:28374/40001908:28368) with its text swapped to "NOTIFY ME" in
  // this state. Authored here in sentence case, not literal caps, matching this codebase's
  // pattern of keeping translatable copy normal-case and letting the textStyle's CSS apply the
  // visual transform (see ZimmProductName's own normal-cased stories against `productNames`'
  // textTransform: 'uppercase') — `linkSm` was corrected to `textTransform: 'uppercase'` to
  // match (2026-09-03, theme/foundation/typography.ts), so this renders "NOTIFY ME" correctly.
  notifyMe: {
    id: 'product_card_content.notify_me.label',
    defaultMessage: 'Notify me',
  },
});

const ZIMM_PRODUCT_CARD_CONTENT_RECIPE = 'ZimmProductCardContent';

/**
 * `ZimmProductName`'s own heading-level prop, read off the atom's real signature via a utility
 * type rather than a hand-typed duplicate union (typescript.md: "prefer utility types over
 * hand-rolled duplicate shapes... a hand-copied type silently drifts from its source when the
 * original changes"). Its type param is `'h1' | 'h2' | 'h3'` — note this is NOT `'h2' | 'h3' |
 * 'h4'` as an earlier sketch of this component's contract assumed; see `headingLevel` below.
 */
type ZimmProductNameHeadingLevel = React.ComponentProps<typeof ZimmProductName>['as'];

export type ZimmProductCardContentProps = {
  /** The product's display name, rendered as the card's heading and link text. */
  name: string;
  /**
   * Heading level for the composed `ZimmProductName`, forwarded to it as `as`. Named
   * `headingLevel` here (rather than `as`) because this component is not itself polymorphic —
   * it always renders the same fixed element tree, it just hands the one real heading a level.
   * Typed as `ZimmProductNameHeadingLevel` (`'h1' | 'h2' | 'h3'`) to exactly match what that atom
   * actually accepts — a prior sketch of this contract assumed `'h2' | 'h3' | 'h4'`, which is
   * wrong on both ends: the atom has no `'h4'` at all, and it does accept `'h1'` (unlikely in
   * practice for a grid card, but not this component's place to forbid what the atom allows).
   */
  headingLevel: ZimmProductNameHeadingLevel;
  /**
   * PDP destination for the product name link. Not passed through `isSafeHref` — unlike
   * `ZimmNavItem`/`ZimmContactIconRow`'s CMS-sourced hrefs, this is an SFCC-generated product URL,
   * the same trust level `ZimmColourSwatch`'s own `href` prop already assumes.
   */
  href: string;
  /** Passed straight through to the composed `ZimmProductPrice`. */
  currentPrice?: string;
  /** Passed straight through to the composed `ZimmProductPrice`. */
  originalPrice?: string;
  /** Passed straight through to `ZimmProductPrice`'s own `isLoading`. */
  isPriceLoading?: boolean;

  /**
   * Wishlist-only attributes line (colour + size as plain text), per the organism's
   * VARIATION_CONFIG (Step 6, not built yet) — this component only ever sees the resolved
   * boolean, never a variation name. When false the row is absent from the DOM entirely, not
   * merely visually hidden.
   */
  showAttributes: boolean;
  /**
   * Rendered only when `showAttributes` is true. Pass the plain colour value ("Ivory", not
   * "Ivory,") — the component itself appends the trailing comma when rendering, matching
   * Figma's own text-node structure (confirmed via get_design_context on node 40002187:58446:
   * the colour text node's own content literally includes the trailing comma, e.g. "Lilac
   * Sand,", not a separate punctuation node). See the `colourWithComma` derivation below.
   */
  colour?: string;
  /** Rendered only when `showAttributes` is true. */
  size?: string;

  /** Renders the bag button (Figma "Icon_bag" — confirmed a bag action, not a wishlist star). */
  showBag: boolean;
  /** Disables the bag button (native `disabled`) when true. `onAddToBag` never fires in that state. */
  isUnavailable?: boolean;
  onAddToBag?: () => void;

  /**
   * PLP-only size-chip picker, per the organism's config. Always rendered in the DOM whenever
   * true — Figma's `hidden=true` default on this slot is a hover-reveal CSS concern for the
   * Step 6 organism, not something this component enforces on itself. See the module docblock's
   * `data-card-slot="sizeChips"` note.
   */
  showSizeChips: boolean;
  sizeChipValues?: ZimmSizeChipValue[];
  selectedSizeChipValue?: string;
  onSizeChipSelect?: (value: string) => void;

  /**
   * True only when the caller has already resolved "unavailable AND a usable notify-me callback
   * exists" (the organism's job). This component still independently requires `onNotifyMe` to be
   * present before rendering anything — belt-and-braces, the same defensive shape
   * `ZimmProductCardMedia`'s own `onRemove` + `removeLabel` co-requirement uses.
   */
  showNotifyMe: boolean;
  onNotifyMe?: () => void;
};

/**
 * Molecule — the product-card text-content block: heading/link, bag action, wishlist-only
 * colour/size attributes, price, PLP-only size-chip picker, and an out-of-stock notify-me CTA.
 * Figma "Card-content" component set, node 40002109:26908 (Desktop 40002109:26906 / Mobile
 * 40002163:37103).
 *
 * Deliberately has NO remove/close button — that action lives entirely in
 * `ZimmProductCardMedia`'s own `close` overlay (Step 4), positioned on the image, not here.
 *
 * Also deliberately has no badge slot, despite the SFCC-236 AC mentioning one for PLP/Wishlist.
 * An earlier revision of this paragraph claimed no Figma design existed for it at all — that
 * was wrong: the badge (Figma "Tag") does exist, confirmed present and identical across every
 * Size/Type variant checked. It just lives inside "Image Group", which is
 * `ZimmProductCardMedia`'s domain, not this component's — so it was built there instead. See
 * that component's own docblock for the confirmed spec, and the organism's own docblock
 * ("Badge" note) for which variations actually show it.
 *
 * Composes `ZimmProductPrice` with `isLive={false}` unconditionally — this is the entire reason
 * that prop exists (SFCC-236 Step 3): a grid of these on a PLP must not mount dozens of
 * `aria-live` regions whose price never changes post-mount.
 */
export const ZimmProductCardContent = ({
  name,
  headingLevel,
  href,
  currentPrice,
  originalPrice,
  isPriceLoading,
  showAttributes,
  colour,
  size,
  showBag,
  isUnavailable,
  onAddToBag,
  showSizeChips,
  sizeChipValues,
  selectedSizeChipValue,
  onSizeChipSelect,
  showNotifyMe,
  onNotifyMe,
}: ZimmProductCardContentProps) => {
  const intl = useIntl();
  // `disabled`, not `isUnavailable` — matches `recipeGuards.test.ts`'s own `DEFAULT_STYLE_PROPS`
  // key so that guard's exhaustive prop-combination walk actually exercises both the true and
  // false branch of `bagButton`'s disabled styling (see zimmProductCardContent.css.ts's own
  // comment, and `zimmSizeChip.css.ts`'s identical `disabled` naming for the same reason).
  const styles = useMultiStyleConfig(ZIMM_PRODUCT_CARD_CONTENT_RECIPE, { disabled: isUnavailable });

  // Both conditions required, matching the component contract exactly — not just `showNotifyMe`
  // alone, so an organism that sets the flag without wiring a real callback silently renders
  // nothing rather than an inert button.
  const showNotifyMeButton = showNotifyMe && Boolean(onNotifyMe);

  // Figma renders the colour/size attributes line as ONE continuous phrase, not two independent
  // labels: the comma is baked into the colour text node's own content ("Lilac Sand,"), not a
  // separate punctuation element — confirmed via get_design_context on node 40002187:58446 (the
  // real Wishlist Card-content instance). Reproduced the same way here, on the colour value's own
  // rendered string (never as a static comma JSX node between the two spans), paired with
  // attributesRow's 2px gap (zimmProductCardContent.css.ts) for the "Ivory, M" breathing room —
  // verified by rendering the real Futura Round Medium caption style at actual size: the glyph
  // ink-to-ink gap the 2px flex gap produces here reads as a genuine (if slightly tighter than
  // full-prose) space, not as "Ivory,M" touching. Guarded against `colour` being falsy so a
  // caller omitting it (a contract violation, but not this component's job to enforce) still
  // renders nothing, rather than the literal string "undefined,".
  const colourWithComma = colour ? `${colour},` : colour;

  return (
    <chakra.div __css={styles.root} data-card-slot={CARD_SLOT.content}>
      <chakra.div __css={styles.nameRow}>
        <ProductNameLink to={href} __css={styles.nameLink}>
          <ZimmProductName name={name} as={headingLevel} />
        </ProductNameLink>

        {showBag && (
          <chakra.div __css={styles.bagWrapper} data-card-slot={CARD_SLOT.bag}>
            <chakra.button
              type="button"
              __css={styles.bagButton}
              aria-label={intl.formatMessage(messages.addToBag)}
              disabled={isUnavailable}
              onClick={() => {
                // Belt-and-braces: the native `disabled` attribute already prevents the browser
                // from ever dispatching this click, but stating the invariant explicitly means a
                // reader doesn't have to recall that fact to trust onAddToBag can't fire while
                // unavailable. Same idiom as ZimmSizeChip's own onClick guard.
                if (isUnavailable) return;
                onAddToBag?.();
              }}
            >
              <ZimmIcon type="bag" aria-hidden />
            </chakra.button>
          </chakra.div>
        )}
      </chakra.div>

      {showAttributes && (
        <chakra.div __css={styles.attributesRow} data-testid="card-content-attributes">
          <chakra.span __css={styles.colourText}>{colourWithComma}</chakra.span>
          <chakra.span __css={styles.sizeText}>{size}</chakra.span>
        </chakra.div>
      )}

      <chakra.div __css={styles.priceWrapper} data-card-slot={CARD_SLOT.price}>
        <ZimmProductPrice
          currentPrice={currentPrice}
          originalPrice={originalPrice}
          isLoading={isPriceLoading}
          isLive={false}
        />
      </chakra.div>

      {showSizeChips && (
        <chakra.div __css={styles.sizeChipWrapper} data-card-slot={CARD_SLOT.sizeChips}>
          <ZimmSizeChipGroup
            values={sizeChipValues ?? []}
            selectedValue={selectedSizeChipValue}
            onSelect={onSizeChipSelect}
          />
        </chakra.div>
      )}

      {showNotifyMeButton && (
        <chakra.button
          type="button"
          __css={styles.notifyMeButton}
          onClick={onNotifyMe}
          data-card-slot={CARD_SLOT.notifyMe}
        >
          {intl.formatMessage(messages.notifyMe)}
        </chakra.button>
      )}
    </chakra.div>
  );
};

export default ZimmProductCardContent;

