export const WithAttributes: Story = {
  args: {
    ...Default.args,
    showAttributes: true,
    colour: 'Ivory',
    size: 'M',
  },
};

/** Wishlist-shaped, one-size product: the size half of the attributes line reads "One size" rather than a real size value. */
export const WithAttributesOneSize: Story = {
  args: {
    ...Default.args,
    showAttributes: true,
    colour: 'Ivory',
    size: 'One size',
  },
};

