 * `[role=radiogroup]` of chips. Plain args here, not wrapped in `WithSizeChipsExample` and with no
 * `selectedSizeChipValue`/`onSizeChipSelect` — there is nothing to select in that branch (it never
 * reaches the chip-click/keyboard-navigation code path at all), so the interactive wrapper this
 * file uses for `WithSizeChips` would misleadingly imply a selection state that doesn't exist here.
 */
export const WithSizeChipsOneSize: Story = {
  args: {
    ...Default.args,
    showSizeChips: true,
    sizeChipValues: [{ value: 'os', label: 'One size' }],
  },
};

